package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.entity.Statuses.ShipmentStatus; import com.shiphappens.logistics.service.LogisticsService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/reports") public class ReportController { private final LogisticsService service; public ReportController(LogisticsService service){this.service=service;} @GetMapping("/shipments/status-summary") Map<String,Long> summary(){Map<String,Long> result=new LinkedHashMap<>();for(ShipmentStatus s:ShipmentStatus.values())result.put(s.name(),service.count(s));return result;} @GetMapping("/delivery-performance") Map<String,Object> performance(){long delivered=service.count(ShipmentStatus.DELIVERED),failed=service.count(ShipmentStatus.FAILED);return Map.of("delivered",delivered,"failed",failed,"successRate",delivered+failed==0?0:Math.round(delivered*10000.0/(delivered+failed))/100.0);}}
